rss.channel:
{{ site_name }} - News & Events
{{ site_url }}/news-events/
Latest news and events from {{ site_name }}
en-us
{% now "r" %}


{% for article in articles %}


    {{ article.title }}
    {{ site_url }}{{ article.get_absolute_url }}
    {{ article.excerpt|default:article.content|truncatewords:50|striptags }}
    {{ article.author.email }} ({{ article.author.get_full_name|default:article.author.username }})
    {{ article.category.name }}
    {{ article.published_date|date:"r" }}
    {{ site_url }}{{ article.get_absolute_url }}

{% endfor %}

{% for event in events %}


    {{ event.title }} (Event)
    {{ site_url }}{{ event.get_absolute_url }}
    {{ event.short_description|default:event.description|truncatewords:50|striptags }} - Event Date: {{ event.event_date|date:"F d, Y" }}
    {{ event.get_event_type_display }}
    {{ event.created_at|date:"r" }}
    {{ site_url }}{{ event.get_absolute_url }}

{% endfor %}
